import os, pathlib, sys
t = pathlib.Path(os.environ["TARGET_DIR"])
candidates = []
for root, dirs, files in os.walk(t):
    for f in files:
        if f.endswith(".py"):
            path = os.path.join(root, f)
            with open(path, 'r', encoding='utf-8', errors='ignore') as fh:
