                    candidates.append(os.path.relpath(path, t))
                elif "subprocess" in content and "pip" in content and "install -e" in content:
                    candidates.append(os.path.relpath(path, t))
if candidates:
    print("Potential harness scripts:")
    for c in set(candidates):
        print(c)
else:
    print("No candidate script found.")
